const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ---------- 1. Global middleware ----------
app.use(helmet());                         // security headers
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || [], // whitelist, empty = deny all
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);
app.use(express.json({ limit: '100kb' })); // body parser with size cap
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: process.env.RATE_LIMIT_MAX ? parseInt(process.env.RATE_LIMIT_MAX) : 100, // limit per IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- 2. Helper: async wrapper ----------
/**
 * Wrap async route handlers so thrown errors are passed to next()
 */
const asyncWrap = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

