## 4️⃣ Refactored `app.js` (example)

Below is a **complete, but still minimal**, rewrite that incorporates the above suggestions while keeping the original functionality intact.

```js
// app.js
'use strict';

// ---------------------------------------------------------------
// 1️⃣ Core dependencies
// ---------------------------------------------------------------
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const xssClean = require('xss-clean');
const asyncHandler = require('./utils/asyncHandler'); // helper from above
require('dotenv').config(); // loads .env (add to .gitignore)

// ---------------------------------------------------------------
// 2️⃣ App initialization
// ---------------------------------------------------------------
const app = express();

// ---------------------------------------------------------------
// 3️⃣ Security & parsing middlewares
// ---------------------------------------------------------------
app.use(helmet());                                 // HTTP header hardening
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' })); // adjust for your domain
app.use(express.json({ limit: '10kb' }));         // body parser with size limit
app.use(xssClean());                               // basic XSS sanitisation

// Rate‑limit for the /users endpoint (adjust as needed)
const usersLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // max 100 requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', usersLimiter);

// ---------------------------------------------------------------
// 4️⃣ Routes
// ---------------------------------------------------------------
app.get(
  '/health',
  asyncHandler(async (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  })
);

// Simple in‑memory user list (replace with DB in prod)
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Optional pagination – validated with Joi (see validation/usersValidator.js)
const { validatePagination } = require('./validation/usersValidator');

app.get(
  '/users',
  validatePagination,
  asyncHandler(async (req, res) => {
    const { page, limit } = req.query;
    const start = (page - 1) * limit;
    const paged = USERS.slice(start, start + limit);
    res.json({
      page,
      limit,
      total: USERS.length,
      data: paged,
    });
  })
);

// ---------------------------------------------------------------
// 5️⃣ 404 handler
// ---------------------------------------------------------------
app.use((_req, _res, next) => {
  const err = new Error('Not Found');
  err.status = 404;
  next(err);
});

// ---------------------------------------------------------------
// 6️⃣ Central error handler
// ---------------------------------------------------------------
app.use((err, _req, res, _next) => {
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  const payload = {
    error: isProd ? (status === 500 ? 'Internal Server Error' : err.message) : err.message,
  };
  if (!isProd) payload.stack = err.stack; // helpful during development

  // Log the error (replace with a proper logger in real code)
  console.error(`[${new Date().toISOString()}] ${err.stack}`);

  res.status(status).json(payload);
});

// ---------------------------------------------------------------
// 7️⃣ Server bootstrap
// ---------------------------------------------------------------
const PORT = process.env.PORT || 3000;
if (require.main === module) {
  // Only start listening when the file is executed directly (helps testing)
  app.listen(PORT, () => {
    console.info(`Server running on port ${PORT}`);
  });
}

// Export the app for unit tests / integration tests
module.exports = app;
```

### What changed?

| Category | Change | Security / Reliability benefit |
|----------|--------|--------------------------------|
| **Headers** | `helmet()` | Reduces attack surface via secure defaults. |
| **CORS** | Configurable whitelist | Prevents unauthorized browsers from calling the API. |
| **Rate limiting** | `express-rate-limit` on `/users` | Thwarts abuse and basic DoS. |
| **Body parsing & size limit** | `express.json({ limit: '10kb' })` | Mitigates request‑body‑bloat attacks. |
| **XSS sanitisation** | `xss-clean` | Removes malicious scripts from incoming JSON. |
| **Environment config** | `dotenv`, `process.env.PORT` | Keeps secrets out of source and enables 12‑factor deployment. |
| **Async wrapper** | `asyncHandler` | Guarantees that thrown errors are funneled to the error middleware. |
| **Input validation** | `validatePagination` (Joi) | Guarantees that `page`/`limit` are numbers and within expected bounds. |
| **Central error handling** | One middleware that logs + hides stack traces in prod | Prevents crashes, avoids leaking internals, provides consistent JSON error response. |
| **404 fallback** | Explicit 404 handler | Avoids “hang” on unknown routes. |
| **Graceful startup guard** | `if (require.main === module)` | Lets test suites import the app without binding the port. |
| **Logging** | Timestamped `console.error/info` (replaceable) | Makes troubleshooting easier and aids audit trails. |
| **Modularisation** | Split validator & async helper in separate files | Improves maintainability and testability. |

