const { body, param, query, validationResult } = require('express-validator');
const morgan = require('morgan');               // lightweight request logger
const pino = require('pino');                   // structured logger (optional)
const enforce = require('express-enforces-ssl'); // optional HTTPS enforcement

/* ------------  App & configuration  ------------ */
const app = express();

// ----- Environment -----
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const isProd = NODE_ENV === 'production';

// ----- Logging -----
const logger = pino({ level: isProd ? 'info' : 'debug' });
app.use(morgan(isProd ? 'combined' : 'dev', {
  stream: {
    write: (msg) => logger.info(msg.trim())
  }
}));

/* ------------  Security middleware  ------------ */
app.use(helmet());                     // Secure HTTP headers
app.disable('x-powered-by');           // Hide Express version

// CORS – adjust the origin list to match your front‑ends
app.use(cors({
  origin: isProd ? ['https://myapp.example.com'] : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  credentials: true
}));

// Body parsers with size limits
app.use(express.json({ limit: '100kb' }));
app.use(express.urlencoded({ extended: true, limit: '100kb' }));

// Rate limiting – 100 requests per 15 min per IP (tune as required)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});
app.use('/users', apiLimiter);   // apply to any heavy endpoint

// Enforce HTTPS in production (defense‑in‑depth)
if (isProd) app.use(enforce());

// ------------------------------------------------------------------
// Helper: wrap async route handlers to forward errors to the error middleware
const asyncHandler = fn => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);
// ------------------------------------------------------------------

/* ------------  Routes  ------------ */

/**
 * Health‑check endpoint – no validation needed.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users – returns a static list for demo purposes.
 * Example of input validation: you could accept `?page=` or `?search=` later.
 */
app.get(
  '/users',
  // Example validation (currently nothing is expected)
  // query('page').optional().isInt({ min: 1 }).toInt(),
  asyncHandler(async (req, res) => {
    // If you later add validation, check for errors early:
    // const errors = validationResult(req);
    // if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];
    res.json(users);
  })
);

/* ------------  404 handler  ------------ */
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not found' });
});

/* ------------  Central error handler  ------------ */
app.use((err, req, res, next) => {
  // Log full error with stack trace (only server‑side)
  logger.error({ err, url: req.originalUrl, method: req.method }, 'Unhandled error');

  const status = err.status || 500;
  const response = {
    error: err.message || 'Internal Server Error'
  };
  // Avoid leaking stack traces in production
  if (!isProd && err.stack) response.stack = err.stack;

  res.status(status).json(response);
});

/* ------------  Server bootstrap  ------------ */
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} (${NODE_ENV})`);
});

/* ------------  Graceful shutdown  ------------ */
function shutdown() {
  logger.info('Received kill signal, shutting down gracefully...');
  server.close(() => {
    logger.info('Closed out remaining connections.');
    process.exit(0);
  });
  // Force quit after 10 seconds
  setTimeout(() => {
    logger.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app; // keep for testing
