/* ---- Centralized error handling --------------------------------------- */
app.use((err, _req, res, _next) => {
  // Distinguish operational errors from programming bugs.
  const isClientError = err.isJoi || err.status && err.status < 500;

  // Log the full stack for operators (but do NOT send it to the client).
  logger.error({ err }, 'Error handling request');

  // Respond with a generic message for server errors.
  const response = {
    error: isClientError ? err.message : 'Internal server error',
  };
  const statusCode = err.status || (isClientError ? 400 : 500);
  res.status(statusCode).json(response);
});

/* ---- Process‑level error listeners ------------------------------------- */
process.on('unhandledRejection', (reason) => {
  logger.fatal({ reason }, 'Unhandled Promise Rejection – exiting');
