* **Rate‑limit** – mitigates brute‑force and DoS.
* **CORS** – whitelists allowed origins.
* **Centralised error‑handling middleware** – converts thrown errors into proper JSON responses without leaking stack traces.
* **Graceful shutdown** – captures `SIGINT/SIGTERM` and uncaught rejections.
* **Environment‑driven configuration** – uses `process.env.PORT` with a safe fallback.
* **Structured logging** – using `morgan` (or a dedicated logger like `winston`).

```js
// ---------------------------------------------------------------
// app.js – hardened Express server
// ---------------------------------------------------------------

require('dotenv').config();                 // Load .env (PORT, CORS_ORIGIN, etc.)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

/* ---------- 1️⃣ Core security middlewares ---------- */
app.use(helmet());                               // Adds CSP, HSTS, X‑Frame‑Options, …
app.use(
  cors({
    origin: process.env.CORS_ORIGIN || '*',    // Change `*` to a whitelist in prod.
    methods: ['GET', 'POST', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  })
);

/* ---------- 2️⃣ Request‑size & rate limiting ---------- */
app.use(express.json({ limit: '100kb' }));      // Prevent huge payloads.
app.use(express.urlencoded({ extended: false }));
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 min
    max: 100,                 // max 100 requests per window per IP
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many requests, please try again later.' },
  })
);

/* ---------- 3️⃣ Logging ---------- */
app.use(morgan('combined'));   // Could be swapped for winston/pino for JSON logs.

/* ---------- 4️⃣ Health endpoint ---------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/* ---------- 5️⃣ Example read‑only "/users" endpoint ---------- */
const staticUsers = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/users', (req, res) => {
  res.json(staticUsers);
});

/* ---------- 6️⃣ Sample POST endpoint showing validation ---------- */
app.post(
  '/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name is required (max 100 chars)'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid e‑mail address required'),
  ],
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 – client sent bad data. No internal details leaked.
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app you’d persist the user to a DB here.
    const newUser = {
      id: staticUsers.length + 1,
      name: req.body.name,
      email: req.body.email,
    };
    staticUsers.push(newUser);
    res.status(201).json(newUser);
  }
);

/* ---------- 7️⃣ Central error‑handling middleware ---------- */
app.use((err, req, res, next) => {
  // Log the error (could be sent to a monitoring service)
  console.error(err);

  // Do NOT expose stack traces in production
  const isProd = process.env.NODE_ENV === 'production';
  const response = {
    error: err.message || 'Internal Server Error',
  };
  if (!isProd && err.stack) {
    response.stack = err.stack;
  }
  res.status(err.status || 500).json(response);
});

/* ---------- 8️⃣ Server bootstrap with graceful shutdown ---------- */
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.info(`🚀 Server listening on http://localhost:${PORT}`);
});

/* Capture startup errors (e.g., EADDRINUSE) */
server.on('error', (err) => {
  console.error('❌ Server startup error:', err);
  process.exit(1);
});

/* Graceful shutdown on SIGINT / SIGTERM */
const shutdown = (signal) => {
  console.info(`🛑 Received ${signal}, closing server...`);
  server.close(() => {
    console.info('✅ Server closed.');
    process.exit(0);
  });
};

process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

/* Catch uncaught exceptions / rejections – prevents process crash silently */
process.on('unhandledRejection', (reason) => {
  console.error('⚠️ Unhandled Promise Rejection:', reason);
});
