### 2.4 Centralised error‑handling middleware

```js
// 1️⃣ 404 handler – catches unknown routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

// 2️⃣ Generic error handler – never leak stack traces in production
app.use((err, req, res, next) => {
  // Log the error (you can replace with winston/pino/etc.)
  console.error(err);

  const status = err.status || 500;
  const response = {
    error: err.message || 'Internal Server Error',
  };

  // In production hide internal details
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});
```

**Why?**  
* Guarantees the process stays up – the response is always sent, even for async errors.  
* Prevents leaking implementation details (`stack`) to the client in production.

### 2.5 Input validation (example for a future **POST /users**)

```js
const { body, validationResult } = require('express-validator');

app.post(
  '/users',
  [
