## 3. Refactored **app.js** (compact version)

Below is a ready‑to‑paste version that incorporates all the above suggestions while preserving the original behaviour. Feel free to split the middleware into separate modules for better maintainability.

```js
/* app.js – secured & robust Express starter */

require('dotenv').config();               // loads .env (dev only)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');
const { body, validationResult } = require('express-validator');

const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
const app = express();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['*'];

/* ---------- Security middleware ---------- */
app.use(helmet());

app.use(
  cors({
    origin: ALLOWED_ORIGINS,
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

/* ---------- Body parsers ---------- */
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: false }));

/* ---------- HTTPS enforcement (prod) ---------- */
if (NODE_ENV === 'production') {
  app.enable('trust proxy');
  app.use((req, res, next) => {
    if (req.secure) return next();
    res.redirect(`https://${req.headers.host}${req.originalUrl}`);
  });
}

/* ---------- Routes ---------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app replace this with DB call and proper auth/authorization
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/* Example POST route with validation */
app.post(
  '/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name is required and must be ≤100 chars'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required'),
  ],
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Simulate user creation
    const { name, email } = req.body;
    const newUser = { id: Date.now(), name, email };
    // Normally insert into DB here
    res.status(201).json(newUser);
  }
);

/* ---------- 404 handler ---------- */
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

/* ---------- Global error handler ---------- */
app.use((err, req, res, next) => {
  logger.error(err);
  const status = err.status || 500;
  const payload = { error: err.message || 'Internal Server Error' };
  if (NODE_ENV !== 'production') payload.stack = err.stack;
  res.status(status).json(payload);
});

/* ---------- Server start ---------- */
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} (mode: ${NODE_ENV})`);
});

/* ---------- Graceful shutdown ---------- */
function shutdown() {
  logger.info('Received termination signal – shutting down...');
  server.close(() => {
    logger.info('Closed remaining connections');
    process.exit(0);
  });
  setTimeout(() => {
    logger.error('Force shutdown');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

/* ---------- Process‑wide error handling ---------- */
process.on('unhandledRejection', (reason, promise) => {
  logger.error({ promise, reason }, 'Unhandled promise rejection');
});
process.on('uncaughtException', err => {
  logger.fatal(err, 'Uncaught Exception – exiting');
  process.exit(1);
});

module.exports = app;
```

**What changed?**

| Category | Change | Security benefit |
|----------|--------|------------------|
| **Headers** | `helmet()` | Mitigates XSS, click‑jacking, MIME sniffing, etc. |
| **CORS** | Configurable whitelist | Prevents unwanted origins from consuming the API |
| **Rate limiting** | `express-rate-limit` | Thwarts brute‑force/DDoS attempts |
| **Body limits** | `express.json({limit:'1mb'})` | Stops memory‑exhaustion attacks |
| **HTTPS redirect** | conditional redirect | Guarantees encrypted transport in prod |
| **Input validation** | `express-validator` on POST `/users` | Ensures only well‑formed data enters the system |
| **Error handling** | Centralised 404 & error handler | Guarantees JSON output, no stack leaks in prod |
| **Logging** | `pino` logger | Structured logs for audit/monitoring |
| **Config** | Environment vars (`PORT`, `ALLOWED_ORIGINS`) | Allows per‑environment hardening |
| **Graceful shutdown** | `SIGTERM`/`SIGINT` handlers | Avoids abrupt termination and resource leaks |
| **Process‑wide error catchers** | `unhandledRejection`, `uncaughtException` | Prevents silent crashes and enables leak detection |

