// ---------------------------------------------------
// app.js – Secure, production‑ready Express starter
// ---------------------------------------------------

// 1️⃣ Core modules & 3rd‑party deps
const express = require('express');
const helmet = require('helmet');                     // security headers
const rateLimit = require('express-rate-limit');     // basic DoS protection
const cors = require('cors');                         // optional CORS handling
const morgan = require('morgan');                     // request logging
const { celebrate, Joi, errors, Segments } = require('celebrate'); // input validation

// 2️⃣ Create the app
const app = express();

// ---------------------------------------------------
// Middleware stack
// ---------------------------------------------------

// Helmet – adds a collection of secure HTTP headers
app.use(helmet());

// CORS – lock down origins (adjust the array to your needs)
const allowedOrigins = ['https://my‑frontend.example.com'];
app.use(
  cors({
    origin: (origin, callback) => {
      if (!origin || allowedOrigins.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    credentials: true,
  })
);

// Rate limiter – simple global limit (tune for your traffic)
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100, // max requests per IP per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parser – Express’s built‑in JSON parser (limit payload size)
app.use(express.json({ limit: '10kb' }));

// Structured request logging (only in non‑test env)
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// ---------------------------------------------------
// Routes
// ---------------------------------------------------

// /health – no validation needed, but keep it lightweight
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// /users – example route with input validation (future‑proof)
// Even though this endpoint only returns static data now,
// adding validation shows the pattern you’ll use for real endpoints.
app.get(
  '/users',
  // Example: optional `limit` query param must be a positive integer ≤ 100
  celebrate({
    [Segments.QUERY]: Joi.object({
      limit: Joi.number().integer().min(1).max(100).optional(),
    }),
  }),
  (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply a simple limit if requested – defensive coding
    const limit = req.query.limit ? Number(req.query.limit) : users.length;
    res.json(users.slice(0, limit));
  }
);

// ---------------------------------------------------
// 3️⃣ Centralised error handling
// ---------------------------------------------------

// Celebrate (Joi) validation errors – must come before generic error handler
app.use(errors());

// Generic error‑handler – never leak stack traces in production
app.use((err, _req, res, _next) => {
  // Log the error (structured logging is preferred)
  console.error(err); // replace with a logger in real code

  // Determine the status code
  const status = err.status || err.statusCode || 500;

  // Hide details unless we’re explicitly in development mode
  const response =
    process.env.NODE_ENV === 'development'
      ? { message: err.message, stack: err.stack }
      : { message: 'Internal Server Error' };

  res.status(status).json(response);
});

// ---------------------------------------------------
// 4️⃣ Server bootstrap & graceful shutdown
// ---------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown (helps with Kubernetes, PM2, etc.)
function shutdown(signal) {
  console.log(`\n${signal} received – shutting down gracefully…`);
  server.close(() => {
    console.log('HTTP server closed.');
    // Close DB connections, flush logs, etc. here
    process.exit(0);
  });

  // Force exit after 10 seconds (optional)
  setTimeout(() => {
    console.error('Forced shutdown.');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;
```

### What changed & why?

| Change | Security / Robustness benefit |
|--------|-------------------------------|
| **helmet** | Sets `X‑Content‑Type‑Options`, `X‑Frame‑Options`, CSP, HSTS, etc., mitigating many attacks (XSS, click‑jacking, MIME sniffing). |
| **cors** | Prevents browsers from making requests from untrusted origins. Adjust the whitelist to your front‑end domains. |
| **express‑rate‑limit** | Thwarts basic DoS / brute‑force attempts, especially on health‑check endpoints that are often scraped. |
| **body‑parser size limit** | Limits request payload size to avoid memory‑exhaustion attacks. |
| **celebrate + Joi** | Declarative input validation; any malformed or unexpected data is rejected with a 400 before reaching business logic. |
| **centralised error middleware** | Guarantees that all errors funnel through one place, letting you log details securely while returning only generic messages to the client in production. |
| **structured logging** (via `morgan` or a full logger) | Makes it easier to audit requests, detect anomalies, and ship logs to a SIEM. |
| **environment‑driven port** | Allows the app to run in containers or on platforms where the port is assigned at runtime. |
| **graceful shutdown** | Prevents abrupt termination that could corrupt in‑flight DB writes or drop connections. |
| **no `console.log` in production** | Replace with a proper logger (e.g., `pino`) that respects log levels and can be routed to centralized log aggregates. |

---

## 3️⃣ Quick “gotchas” to watch out for

1. **Do not expose detailed error messages** – even `err.message` may contain sensitive info (e.g., DB query fragments). Keep it generic unless `NODE_ENV=development`.  
2. **Never trust client‑supplied data**. Even if an endpoint currently returns static data, future changes (e.g., `/users/:id`) must validate the `:id` param (`Joi.number().integer().positive()`).  
3. **CORS vs. CSRF** – If you ever add state‑changing routes (POST/PUT/DELETE) and use cookies or other auth headers, add CSRF protection (`csurf` or same‑site cookies).  
4. **Dependency hygiene** – Run `npm audit` regularly, and consider pinning critical packages (e.g., `helmet@^7.0.0`).  
5. **TLS termination** – In production, the app should sit behind a TLS‑terminating reverse proxy (NGINX, Cloudflare, etc.). Ensure `app.set('trust proxy', true)` if you rely on `req.ip` for rate limiting.

---

## 4️⃣ Suggested next steps for your repo

1. **Add the required packages**  
   ```bash
   npm install helmet cors express-rate-limit morgan celebrate joi
