// app.js
/**
 * Secure Express server – health & users demo
 * Adds security headers, rate limiting, input validation scaffolding,
 * centralized error handling and environment‑driven configuration.
 */

const express = require('express');
const helmet = require('helmet');               // 1️⃣ security headers
const rateLimit = require('express-rate-limit'); // 2️⃣ rate limiting
const morgan = require('morgan');               // 7️⃣ request logging
const { body, param, query, validationResult } = require('express-validator'); // 5️⃣ validation
const createError = require('http-errors');     // helps create proper error objects

const app = express();

// ---------- Configuration ----------
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const IS_PROD = NODE_ENV === 'production';

// ---------- Middleware ----------
app.use(helmet());                                 // security headers
app.use(express.json({ limit: '1mb' }));           // body‑size limiting (3️⃣)
app.use(express.urlencoded({ extended: false })); // for any form‑encoded data

// Structured logging (only in dev prints to console)
app.use(morgan(IS_PROD ? 'combined' : 'dev'));

// Basic rate limiting – 100 requests per 15 min per IP (2️⃣)
// Adjust limits based on your traffic profile.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Routes ----------
app.get('/health', (req, res) => {
  // No user input – nothing to validate
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Future‑proof users endpoint – includes validation skeleton.
 * At the moment we just return static data, but this shows how
 * you would safely handle parameters (e.g., ?page=, ?limit=).
 */
app.get(
  '/users',
  // Example query‑param validation (5️⃣)
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1 and 100'),
  ],
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Send a 400 Bad Request with details (5️⃣)
      return next(createError(400, { validation: errors.array() }));
    }

    // In a real app you would fetch from DB using pagination params.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  }
);

// ---------- 404 handler ----------
app.use((_req, _res, next) => {
  next(createError(404, 'Not Found'));
});

// ---------- Centralized error handler ----------
app.use((err, _req, res, _next) => {
  // Log the error (you could hook a real logger like Winston/Bunyan)
  console.error(err);

  // Hide stack traces from clients in production (4️⃣)
  const response = {
    status: err.status || 500,
    message: err.message || 'Internal Server Error',
  };
  if (!IS_PROD && err.stack) {
    response.stack = err.stack;
  }
  res.status(response.status).json(response);
});

// ---------- Server startup ----------
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (${NODE_ENV})`);
  });

  // Graceful shutdown (10️⃣)
  const gracefulShutdown = () => {
    console.log('Received kill signal, shutting down gracefully...');
    server.close(() => {
      console.log('Closed out remaining connections.');
      process.exit(0);
    });
    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Could not close connections in time, forcing shutdown');
      process.exit(1);
    }, 10_000);
  };
  process.on('SIGTERM', gracefulShutdown);
  process.on('SIGINT', gracefulShutdown);
}

module.exports = app;
```

