| Concern | Recommendation |
|---------|----------------|
| Hard‑coded ports / secrets | Use `process.env.PORT` (default 3000) and `.env` files (via `dotenv`). |
| Running as root | Ensure the Node process drops privileges (e.g., `process.setuid('node')`). |
| Uncaught Promise rejections | `process.on('unhandledRejection', …)` to log and gracefully shut down. |
| Graceful shutdown (SIGTERM/SIGINT) | Close the HTTP server and any DB connections before exit. |

```js
require('dotenv').config(); // load .env (dev only)

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
function shutdown(signal) {
  console.log(`Received ${signal}. Closing server...`);
  server.close(() => {
    console.log('Server closed. Exiting process.');
    process.exit(0);
  });
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));
```

---

## 5️⃣ Miscellaneous best practices

| Practice | How to implement |
|----------|------------------|
| **Enable CORS** *only* where needed | `app.use(cors({ origin: trustedDomain }))` |
| **Prevent HTTP Parameter Pollution** | Use `helmet` (`helmet.hidePoweredBy()`) and verify single‑value query params. |
| **Secure cookies** (if you add session/auth) | `res.cookie('session', token, { httpOnly: true, secure: true, sameSite: 'strict' })` |
| **Content Security Policy** (for any UI you serve) | Set via `helmet.contentSecurityPolicy({ directives: { defaultSrc: ["'self'"] } })` |
| **Static file serving** (if you later expose assets) | Use `express.static` with proper cache headers, and avoid serving hidden files (`dotfiles: 'ignore'`). |

---

## 📦 Revised `app.js` (minimal but production‑ready)

```js
// -----------------------------------------------------------------------------
// app.js – hardened starter for an Express API
// -----------------------------------------------------------------------------
// 1️⃣ Core modules & security middleware
const express   = require('express');
const helmet    = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan    = require('morgan');
require('dotenv').config();                 // .env → process.env

const app = express();

// -------------------------------------------------
// Middleware stack (order matters)
// -------------------------------------------------
app.use(helmet());                           // secure headers
app.set('trust proxy', 1);                  // behind reverse‑proxy?

// Simple rate limiting – tweak as needed
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// Development‑only request logging
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
}

// -------------------------------------------------
// Routes
// -------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app this would be a DB call wrapped in asyncHandler
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// -------------------------------------------------
// Global error handler (must be after all routes)
// -------------------------------------------------
app.use((err, _req, res, _next) => {
  console.error(err); // replace with a proper logger in prod
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// -------------------------------------------------
// Server bootstrap + graceful shutdown
// -------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

function shutdown(sig) {
  console.log(`Received ${sig}. Shutting down…`);
  server.close(() => {
    console.log('Server closed. Exiting.');
    process.exit(0);
  });
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;
```

